#[derive(Debug, Validate, Deserialize)]
struct BookingRequest {
    #[validate(range(min = 1, max = 20))]
    seats: u32,
    #[validate(required)]
    date: Option<NaiveDate>,
}

match request.validate() {
    Ok(()) => create(request).await?,
    Err(errors) => return Err(validation_problem(errors)), // all fields
}

fn validate(req: &BookingRequest) -> Result<(), Vec<Violation>> {
    let mut errors = Vec::new();
    if !(1..=20).contains(&req.seats) {
        errors.push(Violation::new("seats", "range", "must be between 1 and 20"));
    }
    if req.date.is_none() {
        errors.push(Violation::new("date", "missing", "is required"));
    }
    if errors.is_empty() { Ok(()) } else { Err(errors) }
}
